-- Seed 5 initial blog posts into blog_posts
-- Run in Supabase SQL Editor if admin auto-seed is blocked by RLS

insert into blog_posts (title, excerpt, content, image_url, category, author_id, published)
select
  v.title,
  v.excerpt,
  v.content,
  v.image_url,
  v.category,
  (select id from profiles limit 1),
  true
from (
  values
  ('วิธีเลือกเครื่องพิมพ์ให้เหมาะกับธุรกิจขนาดเล็ก','สรุปเกณฑ์เลือกเครื่องพิมพ์สำหรับร้านค้าและออฟฟิศขนาดเล็ก ทั้งความเร็ว ต้นทุนต่อแผ่น และการดูแลระยะยาว','การเลือกเครื่องพิมพ์ให้เหมาะกับธุรกิจควรเริ่มจากปริมาณงานต่อวัน ประเภทเอกสาร และงบประมาณหมึกพิมพ์ หากเน้นงานเอกสารจำนวนมาก เครื่อง Laser มักคุ้มค่าในระยะยาว แต่หากต้องพิมพ์สีบ่อย เครื่อง Ink Tank จะตอบโจทย์กว่า ควรตรวจสอบค่าใช้จ่ายต่อแผ่น การรับประกัน และความพร้อมของอะไหล่ก่อนตัดสินใจ','https://images.unsplash.com/photo-1593642702821-c8da6771f0c6?auto=format&fit=crop&w=1200&q=80','คู่มือการเลือกซื้อ'),
  ('หมึกแท้ vs หมึกเทียบ เลือกแบบไหนให้คุ้มและปลอดภัย','เปรียบเทียบต้นทุน คุณภาพงานพิมพ์ และความเสี่ยงต่อหัวพิมพ์ เพื่อช่วยตัดสินใจให้เหมาะกับรูปแบบการใช้งานจริง','หมึกแท้ให้คุณภาพสม่ำเสมอและลดความเสี่ยงเรื่องหัวพิมพ์อุดตัน ส่วนหมึกเทียบคุณภาพดีสามารถช่วยลดต้นทุนได้มาก หากเลือกแบรนด์ที่ได้มาตรฐานและมีการรับประกัน แนะนำให้เลือกตามลักษณะงาน: งานสำคัญหรือภาพสีควรใช้หมึกแท้ ส่วนงานเอกสารทั่วไปที่พิมพ์ปริมาณมากสามารถใช้หมึกเทียบเกรดดีได้','https://images.unsplash.com/photo-1563514995966-51f71c4224c3?auto=format&fit=crop&w=1200&q=80','ความรู้เรื่องหมึกพิมพ์'),
  ('เช็กลิสต์ดูแลเครื่องพิมพ์รายเดือน ลดปัญหากระดาษติด','รวมขั้นตอนดูแลเครื่องพิมพ์ที่ทำได้เองใน 10 นาที ช่วยยืดอายุการใช้งานและลดค่าใช้จ่ายซ่อมบำรุง','ควรทำความสะอาดลูกยางดึงกระดาษ ตรวจฝุ่นในถาดกระดาษ และพิมพ์ทดสอบหัวพิมพ์อย่างสม่ำเสมอ การวางเครื่องในพื้นที่อากาศถ่ายเทและไม่ชื้นเกินไปช่วยลดการเสื่อมของชิ้นส่วนได้มาก หากพบอาการผิดปกติ เช่น เสียงดังหรือพิมพ์เป็นเส้น ควรตรวจสอบทันทีเพื่อป้องกันความเสียหายลุกลาม','https://images.unsplash.com/photo-1527443154391-507e9dc6c5cc?auto=format&fit=crop&w=1200&q=80','การดูแลรักษา'),
  ('รีวิว Dot Matrix สำหรับงานบิลและฟอร์มต่อเนื่อง','ทำไมธุรกิจจำนวนมากยังเลือก Dot Matrix: ทนทาน พิมพ์สำเนาหลายชั้นได้ และต้นทุนงานเอกสารต่ำในระยะยาว','เครื่อง Dot Matrix เหมาะกับงานที่ต้องพิมพ์กระดาษต่อเนื่องหรือเอกสารสำเนาหลายชั้น เช่น ใบเสร็จและใบกำกับสินค้า จุดเด่นคือความทนทานและต้นทุนต่อหน้าไม่สูง แม้ความเร็วและคุณภาพภาพจะไม่เท่า Laser แต่ถือว่าคุ้มค่าสำหรับงานเฉพาะทางที่ต้องการความเสถียร','https://images.unsplash.com/photo-1612196808214-b7e239e5d3f0?auto=format&fit=crop&w=1200&q=80','รีวิวสินค้า'),
  ('5 อาการที่บอกว่าควรเช็กเครื่องพิมพ์ก่อนพังหนัก','หากเครื่องเริ่มพิมพ์จาง มีกลิ่นไหม้ หรือเสียงผิดปกติ อย่ารอจนหยุดทำงาน ควรตรวจเช็กทันที','สัญญาณเตือนที่พบบ่อยคือกระดาษติดซ้ำๆ พิมพ์ไม่ติดทั้งที่มีหมึก เสียงมอเตอร์ผิดปกติ และขึ้น Error บ่อย หากเจออาการเหล่านี้ ควรหยุดใช้งานชั่วคราวและตรวจระบบป้อนกระดาษ หัวพิมพ์ หรือชุดทำความร้อน เพื่อป้องกันความเสียหายที่ต้องซ่อมใหญ่และมีค่าใช้จ่ายสูง','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1200&q=80','การดูแลรักษา')
) as v(title, excerpt, content, image_url, category)
where not exists (select 1 from blog_posts);
